from app.database import db

class User:
    """
    Represents a user in the ACM Problem-Solving Platform system.
    """
    def __init__(self, username, email):
        self.username = username
        self.email = email

    def __repr__(self):
        return f"<User(username='{self.username}', email='{self.email}')>"

from flask import Blueprint, jsonify
from app.models.problem import Problem
from app.database import db

problem_bp = Blueprint('problem', __name__)

@problem_bp.route('/problems', methods=['GET'])
def get_problems():
    problems = Problem.query.all()
    problems_data = [{'id': p.id, 'title': p.title, 'description': p.description} for p in problems]
    return jsonify(problems_data)

@problem_bp.route('/problems/<int:problem_id>', methods=['GET'])
def get_problem(problem_id):
    problem = Problem.query.get(problem_id)
    if problem is None:
        return jsonify({'error': 'Problem not found'}), 404
    problem_data = {'id': problem.id, 'title': problem.title, 'description': problem.description}
    return jsonify(problem_data)

from flask import Blueprint, jsonify
from app.models.user import User
from app.database import db

user_bp = Blueprint('user', __name__)

@user_bp.route('/users', methods=['GET'])
def get_users():
    users = User.query.all()
    users_list = [{'id': user.id, 'name': user.name, 'email': user.email} for user in users]
    return jsonify(users_list)

@user_bp.route('/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    user = User.query.get(user_id)
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify({'id': user.id, 'name': user.name, 'email': user.email})

@user_bp.route('/users', methods=['POST'])
def create_user():
    # Example implementation - adjust based on actual data structure
    # Assuming request.json contains {'name': '...', 'email': '...'}
    from flask import request
    data = request.json
    if not data or not data.get('name') or not data.get('email'):
        return jsonify({'error': 'Invalid input'}), 400
    new_user = User(name=data['name'], email=data['email'])
    db.session.add(new_user)
    db.session.commit()
    return jsonify({'message': 'User created', 'id': new_user.id}), 201

@user_bp.route('/users/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    from flask import request
    data = request.json
    user = User.query.get(user_id)
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    if not data:
        return jsonify({'error': 'Invalid input'}), 400
    user.name = data.get('name', user.name)
    user.email = data.get('email', user.email)
    db.session.commit()
    return jsonify({'message': 'User updated'})

@user_bp.route('/users/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    user = User.query.get(user_id)
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    db.session.delete(user)
    db.session.commit()
    return jsonify({'message': 'User deleted'})

from flask import Blueprint, jsonify
from app.models.solution import Solution
from app.database import db

solution_bp = Blueprint('solution', __name__)

@solution_bp.route('/solutions', methods=['GET'])
def get_solutions():
    try:
        solutions = Solution.query.all()
        solutions_data = [solution.to_dict() for solution in solutions]
        return jsonify(solutions_data), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@solution_bp.route('/solutions/<int:solution_id>', methods=['GET'])
def get_solution(solution_id):
    try:
        solution = Solution.query.get(solution_id)
        if not solution:
            return jsonify({'error': 'Solution not found'}), 404
        return jsonify(solution.to_dict()), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@solution_bp.route('/solutions', methods=['POST'])
def create_solution():
    try:
        data = request.get_json()
        solution = Solution(**data)
        db.session.add(solution)
        db.session.commit()
        return jsonify(solution.to_dict()), 201
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@solution_bp.route('/solutions/<int:solution_id>', methods=['PUT'])
def update_solution(solution_id):
    try:
        solution = Solution.query.get(solution_id)
        if not solution:
            return jsonify({'error': 'Solution not found'}), 404
        data = request.get_json()
        for key, value in data.items():
            setattr(solution, key, value)
        db.session.commit()
        return jsonify(solution.to_dict()), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@solution_bp.route('/solutions/<int:solution_id>', methods=['DELETE'])
def delete_solution(solution_id):
    try:
        solution = Solution.query.get(solution_id)
        if not solution:
            return jsonify({'error': 'Solution not found'}), 404
        db.session.delete(solution)
        db.session.commit()
        return jsonify({'message': 'Solution deleted successfully'}), 200
    except Exception as e:
        return jsonify({'error': str(e)}), 500

/* static/css/style.css */
/* Purpose: Frontend styling for the ACM Problem-Solving Platform */

/* General styles */
body {
  font-family: Arial, sans-serif;
  margin: 0;
  padding: 0;
  background-color: #f8f9fa;
  color: #212529;
}

h1, h2, h3, h4, h5, h6 {
  font-weight: bold;
  color: #343a40;
}

a {
  text-decoration: none;
  color: #007bff;
}

a:hover {
  color: #0056b3;
  text-decoration: underline;
}

/* Header styles */
header {
  background-color: #007bff;
  color: white;
  padding: 10px 15px;
}

header nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

header nav a {
  margin: 0 10px;
  font-size: 1rem;
}

/* Button styles */
button {
  background-color: #007bff;
  color: white;
  border: none;
  padding: 10px 15px;
  font-size: 1rem;
  border-radius: 5px;
  cursor: pointer;
}

button:hover {
  background-color: #0056b3;
}

/* Form styles */
form {
  margin: 20px 0;
}

form input, form textarea, form select {
  width: 100%;
  padding: 10px;
  margin: 10px 0;
  border: 1px solid #ced4da;
  border-radius: 5px;
}

form input:focus, form textarea:focus, form select:focus {
  outline: none;
  border-color: #007bff;
}

/* Table styles */
table {
  width: 100%;
  border-collapse: collapse;
  margin: 20px 0;
}

table th, table td {
  border: 1px solid #dee2e6;
  padding: 10px;
  text-align: left;
}

table th {
  background-color: #007bff;
  color: white;
}

table tr:nth-child(even) {
  background-color: #f2f2f2;
}

/* Footer styles */
footer {
  background-color: #343a40;
  color: white;
  text-align: center;
  padding: 10px 0;
  margin-top: 20px;
}

/* Responsive styles */
@media (max-width: 768px) {
  header nav {
    flex-direction: column;
  }

  table {
    font-size: 0.9rem;
  }
}

